    const brick = firstBrick;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    currentX += currentVX * dt * minT;
    currentY += currentVY * dt * minT;
    timeRemaining -= minT;

    const centerX = brick.x + brick.w / 2;
